        <option value="1/4">QUANT: 1/4</option>
        <option value="1/8">QUANT: 1/8</option>
        <option value="1/16">QUANT: 1/16</option>
        <option value="1/32">QUANT: 1/32</option>
      </select>
      <div id="bpm-editor" class="bpm-editor">
