                const binding = currentWorkingLayout[code];
                noteEl.textContent = binding.shiftName || binding.shiftAction || binding.name || k.note || '';
              } else if (data.shiftHeld && k.shiftNote !== undefined) {
                noteEl.textContent = k.shiftNote;
              } else if (k.note !== undefined) {
                noteEl.textContent = k.note;
              }
            }

            const builtIn = typeof getBuiltInKey !== 'undefined' ? getBuiltInKey(code) || {} : {};
            const halfTop = el.querySelector('.key-half-top .key-note');
            const halfBottom = el.querySelector('.key-half-bottom .key-note');
            if (halfTop) {
              if ((currentWorkingLayout || {})[code]) {
                const binding = currentWorkingLayout[code];
                halfTop.textContent = binding.shiftName || binding.shiftAction || k.shiftNote || k.shiftAction || builtIn.shiftLabel || k.note || builtIn.noteLabel || builtIn.keyLabel || '';
              } else {
                halfTop.textContent = k.shiftNote || k.shiftAction || builtIn.shiftLabel || k.note || builtIn.noteLabel || builtIn.keyLabel || '';
              }
            }
            if (halfBottom) {
              if ((currentWorkingLayout || {})[code]) {
                const binding = currentWorkingLayout[code];
                halfBottom.textContent = binding.name || binding.action || k.note || builtIn.noteLabel || builtIn.keyLabel || '';
              } else {
                halfBottom.textContent = k.note || builtIn.noteLabel || builtIn.keyLabel || '';
              }
            }
            const baseClass = 'key-pad ' + (k.isControl ? 'control-pad ' : '') + (k.typeClass || '');
            if (el.dataset.baseClass !== baseClass) {
              const currentStatusClasses = Array.from(el.classList).filter(c =>
                ['latched-key', 'pressed', 'sustain-active', 'arp-held', 'arp-playing', 'trk-selected', 'trk-muted', 'trk-soloed', 'trk-audio-active', 'trk-human-active', 'trk-arp-step'].includes(c)
              );
              el.className = baseClass + (currentStatusClasses.length ? ' ' + currentStatusClasses.join(' ') : '');
              el.dataset.baseClass = baseClass;
            }

            const isLatchedNote = !k.isControl && (
              !!k.latched || 
              (data.arpHeldNotes && (
                !!data.arpHeldNotes[code] || 
                !!data.arpHeldNotes[code + "_"]
              ))
            );
            el.classList.toggle('latched-key', !!isLatchedNote);
            el.classList.toggle('pressed', !!k.pressed);
            el.classList.toggle('sustain-active', isTrkBtn ? false : !!k.sustainActive);
            el.classList.toggle('arp-held', !!k.arpHeld);
            el.classList.toggle('arp-playing', !!k.arpPlaying);

            if (isTrkBtn) {
              if (k.trkSelected !== undefined) el.classList.toggle('trk-selected', !!k.trkSelected);
              if (k.trkMuted !== undefined) {
                el.classList.toggle('trk-muted', !!k.trkMuted);
                const m = el.querySelector('.trk-badge-m');
                if (m) m.classList.toggle('active', !!k.trkMuted);
              }
              if (k.trkSoloed !== undefined) {
                el.classList.toggle('trk-soloed', !!k.trkSoloed);
                const s = el.querySelector('.trk-badge-s');
                if (s) s.classList.toggle('active', !!k.trkSoloed);
              }
              if (k.trkAudioActive !== undefined) el.classList.toggle('trk-audio-active', !!k.trkAudioActive);
              if (k.trkHumanActive !== undefined) el.classList.toggle('trk-human-active', !!k.trkHumanActive);
              if (k.trkArpStep !== undefined) el.classList.toggle('trk-arp-step', !!k.trkArpStep);
            }

            const isShift = data.shiftHeld || shiftModeActive;
            const effAction = isShift ? (k.shiftAction || k.action) : k.action;

            const iconEl = el.querySelector('.key-row-icon');
            if (iconEl) {
              iconEl.classList.remove('top-active', 'bottom-active', 'both-active');

              let rowTarget = k.rowActive || null;
              const curNote = (k.displayNote || k.note || '').trim();

              if (!rowTarget && curNote) {
                if (/^Top(Oct| Vol| 3⇄4| Lock|\b)/i.test(curNote)) {
                  rowTarget = 'top';
                } else if (/^Bot(Oct| Vol| 1⇄2| Lock|\b)/i.test(curNote)) {
                  rowTarget = 'bottom';
                } else if (/^(Oct [+\-]|Oct Reset|Vol [+\-]|Mix Reset)/i.test(curNote)) {
                  rowTarget = 'both';
                }
              }

              if (!rowTarget && effAction) {
                if (
                  effAction === 'topOctDown' || effAction === 'topOctUp' ||
                  effAction === 'topVolDown' || effAction === 'topVolUp' ||
                  effAction === 'arpTopToggle' || effAction === 'topTrackToggle' ||
                  effAction === 'topTrackLock' || effAction === 'topBoostUp' || effAction === 'topBoostDown' ||
                  String(effAction).match(/^trk(Select|Mute|Solo|Lock|Rec|Clear|Focus)[34]$/)
                ) {
                  rowTarget = 'top';
                } else if (
                  effAction === 'botVolDown' || effAction === 'botVolUp' ||
                  effAction === 'arpBottomToggle' || effAction === 'botOctDown' || effAction === 'botOctUp' ||
                  effAction === 'botTrackToggle' || effAction === 'botTrackLock' ||
                  String(effAction).match(/^trk(Select|Mute|Solo|Lock|Rec|Clear|Focus)[12]$/)
                ) {
                  rowTarget = 'bottom';
                } else if (
                  effAction === 'octaveDown' || effAction === 'octaveUp' || effAction === 'octReset' ||
                  effAction === 'volDown' || effAction === 'volUp' || effAction === 'mixReset' ||
                  effAction === 'arpLinkToggle' || effAction === 'splitArpToggle'
                ) {
                  rowTarget = 'both';
                }
              }

              if (!rowTarget && isTrkBtn) {
                rowTarget = (numCode <= 19) ? 'bottom' : 'top';
              }

              if (rowTarget === 'top') {
                iconEl.classList.add('top-active');
              } else if (rowTarget === 'bottom') {
                iconEl.classList.add('bottom-active');
              } else if (rowTarget === 'both') {
                iconEl.classList.add('both-active');
              }
            }
          }
        }
      }

      if (data.arpHeldNotes) {
        for (const [code, isHeld] of Object.entries(data.arpHeldNotes)) {
          const el = document.getElementById('key-' + code);
          if (el && isHeld) {
            el.classList.add('latched-key');
          }
        }
      }

      const renderTime = performance.now() - t0;
      if ((renderTime > 15 || renderCount === 0) && window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'log', message: 'renderHud completed in ' + renderTime.toFixed(2) + 'ms' });
      }
    } catch (err) {
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'log', message: 'CRITICAL renderHud ERROR: ' + (err.stack || err) });
      }
    }
  }

  // Immediate init execution in case DOM ready state passed
  const t0 = performance.now();
  initGrid(LAYOUT_DATA);
  const t1 = performance.now();
  if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
      window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'log', message: 'initGrid took ' + (t1 - t0) + ' ms' });
  }

  // Heartbeat: let Lua detect if the web content process silently dies
  let hbCount = 0;
  setInterval(() => {
    hbCount++;
    if (hbCount >= 10) {
       hbCount = 0;
       if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
          window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'log', message: 'heartbeat tick' });
       }
    }
    if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
      window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'heartbeat' });
    }
  }, 2000);

  window.pingHudController = function() {
    if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
      window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'pong', timestamp: Date.now() });
    }
  };

window.updateArpPitches = function(activeCodes, heldCodes, trkAudioStates) {
  document.querySelectorAll('.key-pad.arp-playing').forEach(el => {
    el.classList.remove('arp-playing');
    if (!el.dataset.physicallyPressed) el.classList.remove('pressed');
  });
  document.querySelectorAll('.key-pad.arp-held').forEach(el => el.classList.remove('arp-held'));
  if (Array.isArray(activeCodes)) {
    activeCodes.forEach(code => {
      const el = document.getElementById('key-' + code);
      if (el && !el.classList.contains('control-pad')) {
        el.classList.add('arp-playing', 'pressed');
      }
    });
  }
  if (Array.isArray(heldCodes)) {
    heldCodes.forEach(code => {
      const el = document.getElementById('key-' + code);
      if (el && !el.classList.contains('control-pad')) {
        el.classList.add('arp-held', 'latched-key');
      }
    });
  }
  if (trkAudioStates && typeof trkAudioStates === 'object') {
    const trkCodeMap = { 1: 18, 2: 19, 3: 20, 4: 21 };
    for (let id = 1; id <= 4; id++) {
      const st = trkAudioStates[id];
      const el = document.getElementById('key-' + trkCodeMap[id]);
      if (el) {
        if (typeof st === 'boolean') {
          el.classList.toggle('trk-audio-active', st);
        } else if (st && typeof st === 'object') {
          if (st.selected !== undefined) el.classList.toggle('trk-selected', !!st.selected);
          if (st.muted !== undefined) {
            el.classList.toggle('trk-muted', !!st.muted);
            const m = el.querySelector('.trk-badge-m');
            if (m) m.classList.toggle('active', !!st.muted);
          }
          if (st.soloed !== undefined) {
            el.classList.toggle('trk-soloed', !!st.soloed);
            const s = el.querySelector('.trk-badge-s');
            if (s) s.classList.toggle('active', !!st.soloed);
          }
          if (st.activeAudio !== undefined) el.classList.toggle('trk-audio-active', !!st.activeAudio);
          if (st.humanActive !== undefined) el.classList.toggle('trk-human-active', !!st.humanActive);
          if (st.arpStep !== undefined) el.classList.toggle('trk-arp-step', !!st.arpStep);
        }
      }
    }
  }
};

window.updateKeyState = function(code, pressed, latched) {
  const el = document.getElementById('key-' + code);
  if (el) {
    if (pressed) el.dataset.physicallyPressed = 'true';
    else delete el.dataset.physicallyPressed;
    el.classList.toggle('pressed', !!pressed || (el.classList.contains('arp-playing')));
    el.classList.toggle('latched-key', !!latched);

    // Also illuminate chiclet key if in nanoKEY view
    const noteEl = el.querySelector(':scope > .key-note') || el.querySelector('.key-note');
    if (noteEl && noteEl.textContent) {
      const noteTxt = noteEl.textContent.trim();
      const nkKeys = document.querySelectorAll('.nk-key-white, .nk-key-black');
      for (let i = 0; i < nkKeys.length; i++) {
        const nameEl = nkKeys[i].querySelector('.nk-key-name');
        if (nameEl && nameEl.textContent.trim() === noteTxt) {
          nkKeys[i].classList.toggle('active', !!pressed);
          break;
        }
      }
    }
  }
};

/* ── Hardware Connection & Dynamic Surface Stacking ── */
window.nanokeyConnected = false;

window.setNanokeyConnected = function(connected) {
  window.nanokeyConnected = !!connected;

  const perfView = document.getElementById('performance-view');
  const nanoView = document.getElementById('nanokey-view');
  const hudContainer = document.getElementById('hud-container');
  const badge = document.getElementById('nanokey-badge');

  if (perfView) {
    perfView.style.display = 'flex';
  }

  if (nanoView) {
    nanoView.style.display = connected ? 'flex' : 'none';
  }

  if (hudContainer) {
    if (connected) {
      hudContainer.classList.add('nanokey-connected');
    } else {
      hudContainer.classList.remove('nanokey-connected');
    }
  }

  if (badge) {
    badge.style.display = connected ? 'inline-flex' : 'none';
  }

  const dot = document.getElementById('nk-status-dot');
  if (dot) dot.classList.toggle('connected', !!connected);
};

window.setSurface = function(surface, notifyHost) {
  // Compatibility shim: QWERTY and nanoKEY are now stacked simultaneously when connected
};

window.onSurfaceChanged = function(surface) {
  // Compatibility shim
};

window.updateNanoKeyState = function(controlId, value, pressed, layer, extra) {
  extra = extra || {};
  const nkView = document.getElementById('nanokey-view');
  if (!nkView) return;

  if (controlId === 'connection') {
    window.setNanokeyConnected(!!pressed);
    return;
  }

  // Layer switches (base, macro_sustain, macro_scene, macro_both)
  if (controlId === 'layer') {
    const isSustain = (layer === 'macro_sustain' || layer === 'macro_both');
    const isScene = (layer === 'macro_scene' || layer === 'macro_both');
    nkView.classList.toggle('sustain-active', isSustain);
    nkView.classList.toggle('scene-active', isScene);
    const btnSus = document.getElementById('nk-btn-sustain');
    if (btnSus) btnSus.classList.toggle('active', isSustain);
    const btnScn = document.getElementById('nk-btn-scene');
    if (btnScn) btnScn.classList.toggle('active', isScene);

    document.querySelectorAll('.nk-pad-macro').forEach(el => {
      if (isScene && el.dataset.scene) {
        el.textContent = el.dataset.scene;
      } else if (isSustain && el.dataset.sustain) {
        el.textContent = el.dataset.sustain;
      }
    });
    return;
  }

  // Sustain button (CC #25)
  if (controlId === 'btn_sustain') {
    const btnSus = document.getElementById('nk-btn-sustain');
    if (btnSus) btnSus.classList.toggle('active', !!pressed);
    nkView.classList.toggle('sustain-active', !!pressed);
    document.querySelectorAll('.nk-pad-macro').forEach(el => {
      if (pressed && el.dataset.sustain) el.textContent = el.dataset.sustain;
    });
    return;
  }

  // Scene button (SysEx)
  if (controlId === 'btn_scene') {
    const btnScn = document.getElementById('nk-btn-scene');
    if (btnScn) btnScn.classList.toggle('active', !!pressed);
    nkView.classList.toggle('scene-active', !!pressed);
    document.querySelectorAll('.nk-pad-macro').forEach(el => {
      if (pressed && el.dataset.scene) el.textContent = el.dataset.scene;
    });
    return;
  }

  // Scale Guide button
  if (controlId === 'btn_guide') {
    const btnG = document.getElementById('nk-btn-scale-guide');
    if (btnG) btnG.classList.toggle('active', !!pressed);
    nkView.classList.toggle('scale-guide-active', !!pressed);
    return;
  }

  // Rotary Knobs (knob_1 .. knob_8)
  if (typeof controlId === 'string' && controlId.indexOf('knob_') === 0) {
    const knobIdx = controlId.replace('knob_', '');
    const dial = document.getElementById('nk-knob-' + knobIdx);
    const valEl = document.getElementById('nk-knob-val-' + knobIdx);
    const ccEl = document.getElementById('nk-knob-cc-' + knobIdx);
    if (dial && value !== null && value !== undefined) {
      const angle = -135 + (value / 127) * 270;
      dial.style.transform = 'rotate(' + angle.toFixed(1) + 'deg)';
    }
    if (valEl && value !== null && value !== undefined) {
      valEl.textContent = value;
    }
    if (ccEl && extra && extra.cc) {
      ccEl.textContent = 'CC ' + extra.cc;
    }
    return;
  }

  // Kaoss Touchpad (Touch X = CC 1 / CC 28; Touch Y = CC 2 / CC 29)
  if (controlId === 'cc_1' || controlId === 'cc_28') {
    const cur = document.getElementById('nk-touch-cursor');
    const xEl = document.getElementById('nk-touch-x');
    if (cur && value !== null && value !== undefined) cur.style.left = (value / 127 * 100).toFixed(1) + '%';
    if (xEl && value !== null && value !== undefined) xEl.textContent = value;
    return;
  }
  if (controlId === 'cc_2' || controlId === 'cc_29' || controlId === 'cc_19') {
    const cur = document.getElementById('nk-touch-cursor');
    const yEl = document.getElementById('nk-touch-y');
    if (cur && value !== null && value !== undefined) cur.style.top = ((127 - value) / 127 * 100).toFixed(1) + '%';
    if (yEl && value !== null && value !== undefined) yEl.textContent = value;
    return;
  }

  // Trigger Pads (pad_1 .. pad_8)
  if (typeof controlId === 'string' && controlId.indexOf('pad_') === 0) {
    const padIdx = controlId.replace('pad_', '');
    const pad = document.getElementById('nk-pad-' + padIdx);
    if (pad) {
      pad.classList.toggle('active', !!pressed);
      if (pressed) {
        pad.classList.add('fired');
        setTimeout(() => pad.classList.remove('fired'), 120);
      }
      if (extra && extra.chord) {
        const chordEl = pad.querySelector('.nk-pad-chord');
        if (chordEl) chordEl.textContent = extra.chord;
      }
    }
    return;
  }

  // Keyboard Keys (key_<note> with automatic octave folding into 48..72)
  if (typeof controlId === 'string' && controlId.indexOf('key_') === 0) {
    const rawNote = parseInt(controlId.replace('key_', ''), 10);
    if (!isNaN(rawNote)) {
      if (!window._activeNanoKeyNotes) window._activeNanoKeyNotes = {};
      if (pressed) {
        window._activeNanoKeyNotes[rawNote] = true;
      } else {
        delete window._activeNanoKeyNotes[rawNote];
      }

      let mapped = rawNote;
      while (mapped < 48) mapped += 12;
      while (mapped > 72) mapped -= 12;

      let isStillActive = false;
      for (const nStr in window._activeNanoKeyNotes) {
        let n = parseInt(nStr, 10);
        while (n < 48) n += 12;
        while (n > 72) n -= 12;
        if (n === mapped) {
          isStillActive = true;
          break;
        }
      }

      const key = document.getElementById('nk-key-' + mapped);
      if (key) {
        key.classList.toggle('active', isStillActive);
      }
    }
    return;
  }
};

// Interactive event handlers for nanoKEY hardware GUI
document.addEventListener('DOMContentLoaded', () => {
  // 1. Sustain Button (Toggle Sustain CC #64 & Macro Layer)
  const btnSustain = document.getElementById('nk-btn-sustain');
  if (btnSustain) {
    btnSustain.addEventListener('click', (e) => {
      e.stopPropagation();
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'nanokeySustain', toggle: true });
      }
    });
  }

  // 2. Scene Button (Toggle Scene SysEx & Macro Layer)
  const btnScene = document.getElementById('nk-btn-scene');
  if (btnScene) {
    btnScene.addEventListener('click', (e) => {
      e.stopPropagation();
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'nanokeyScene', toggle: true });
      }
    });
  }

  // 2b. Scale Guide Button (Toggle Scale Guide & Hardware Key LEDs)
  const btnScaleGuide = document.getElementById('nk-btn-scale-guide');
  if (btnScaleGuide) {
    btnScaleGuide.addEventListener('click', (e) => {
      e.stopPropagation();
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({ type: 'nanokeyGuide', toggle: true });
      }
    });
  }

  // 3. Trigger Pads (Mouse interaction + MIDI/Macro trigger)
  document.querySelectorAll('.nk-pad').forEach(pad => {
    const padIdx = parseInt(pad.dataset.pad, 10);
    const triggerPad = (pressed) => {
      pad.classList.toggle('active', pressed);
      if (pressed) {
        pad.classList.add('fired');
        setTimeout(() => pad.classList.remove('fired'), 120);
      }
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({
          type: 'nanokeyPad',
          pad: padIdx,
          pressed: pressed
        });
      }
    };

    pad.addEventListener('mousedown', (e) => {
      e.preventDefault();
      triggerPad(true);
    });
    pad.addEventListener('mouseup', (e) => {
      e.preventDefault();
      triggerPad(false);
    });
    pad.addEventListener('mouseleave', (e) => {
      if (pad.classList.contains('active')) triggerPad(false);
    });
  });

  // 4. Chiclet Keys (Mouse interaction + MIDI Note trigger)
  document.querySelectorAll('.nk-key-white, .nk-key-black').forEach(key => {
    const noteNum = parseInt(key.dataset.note, 10);
    const triggerKey = (pressed) => {
      key.classList.toggle('active', pressed);
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.midiControllerUC) {
        window.webkit.messageHandlers.midiControllerUC.postMessage({
          type: 'nanokeyKey',
          note: noteNum,
          pressed: pressed
        });
      }
    };

    key.addEventListener('mousedown', (e) => {
      e.preventDefault();
      triggerKey(true);
    });
    key.addEventListener('mouseup', (e) => {
      e.preventDefault();
      triggerKey(false);
    });
    key.addEventListener('mouseleave', (e) => {
      if (key.classList.contains('active')) triggerKey(false);
    });
  });
});

</script>
</body>
</html>
]]

return HTML_UI_CONTENT

